import {ToolRegistry} from './registry.js';
import Ajv from 'ajv';

describe('ToolRegistry', () => {
  it('throws at registration time naming the tool for an uncompilable schema', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_lookup',
          description: 'Tool with an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {
              query: {type: 'not-a-json-schema-type'},
            },
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_lookup/);
  });

  it('asserts valid input with an unlisted extra property is passed through to the executor unchanged', async () => {
    const registry = new ToolRegistry();
    let receivedInput: any;
    registry.register(
      {
        name: 'test_tool',
        description: 'test',
        inputSchema: {type: 'object', properties: {a: {type: 'string'}}},
      },
      async input => {
        receivedInput = input;
        return 'ok';
      }
    );

    await registry.execute('test_tool', {a: 'val', extra: 123});
    expect(receivedInput).toEqual({a: 'val', extra: 123});
  });

  it('throws Unknown tool for an unregistered name', async () => {
    const registry = new ToolRegistry();
    await expect(registry.execute('missing', {})).rejects.toThrow('Unknown tool: missing');
  });

  it('asserts a function-valued tool definition whose returned schema differs between calls is validated against the schema current at that call', async () => {
    const registry = new ToolRegistry();
    let requiredField = 'first';

    registry.register(
      () => ({
        name: 'dynamic_tool',
        description: 'test',
        inputSchema: {
          type: 'object',
          properties: {[requiredField]: {type: 'string'}},
          required: [requiredField],
        },
      }),
      async () => 'ok'
    );

    // First call: 'first' is required
    const res1 = await registry.execute('dynamic_tool', {first: 'hi'});
    expect(res1.result).toBe('ok');

    const res2 = await registry.execute('dynamic_tool', {});
    expect(res2.result).toContain('first');

    // Second call: 'second' is required
    requiredField = 'second';
    const res3 = await registry.execute('dynamic_tool', {second: 'hi'});
    expect(res3.result).toBe('ok');

    const res4 = await registry.execute('dynamic_tool', {first: 'hi'});
    expect(res4.result).toContain('second');
  });

  it('asserts a static tool schema is compiled once across many execute calls', async () => {
    const compileSpy = jest.spyOn(Ajv.prototype, 'compile');
    const registry = new ToolRegistry();
    const schema = {type: 'object', properties: {a: {type: 'string'}}};

    registry.register(
      {
        name: 'static_tool',
        description: 'test',
        inputSchema: schema,
      },
      async () => 'ok'
    );

    const initialCompileCount = compileSpy.mock.calls.length;

    for (let i = 0; i < 10; i++) {
      await registry.execute('static_tool', {a: 'val'});
    }

    expect(compileSpy.mock.calls.length).toBe(initialCompileCount);
    compileSpy.mockRestore();
  });
});

